import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"MVC・MVP・MVVM — 画面の責務を分ける","description":"","frontmatter":{"title":"MVC・MVP・MVVM — 画面の責務を分ける","study":{"source":"設計の手帖","kind":"本文","status":"既存原稿","summary":"画面のイベントハンドラーに全部書く状態から抜け出すために、入力・表示・状態の置き場所を考えます。"}},"headers":[],"relativePath":"design/notebook/presentation.md","filePath":"design/notebook/presentation.md"}'),d={name:"design/notebook/presentation.md"};function i(n,e,l,s,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mvc・mvp・mvvm-—-画面の責務を分ける" tabindex="-1">MVC・MVP・MVVM — 画面の責務を分ける <a class="header-anchor" href="#mvc・mvp・mvvm-—-画面の責務を分ける" aria-label="Permalink to &quot;MVC・MVP・MVVM — 画面の責務を分ける&quot;">​</a></h1><p>画面のイベントハンドラーに全部書く状態から抜け出すために、入力・表示・状態の置き場所を考えます。</p><p>03 · アプリ全体を設計する / MVC・MVP・MVVM / Separate the screen from the rules / 基礎 / 9分</p><p>タグ: MVC / MVP / MVVM / Controller / Presenter / ViewModel</p><h2 id="三つの構成を比較する" tabindex="-1">三つの構成を比較する <a class="header-anchor" href="#三つの構成を比較する" aria-label="Permalink to &quot;三つの構成を比較する&quot;">​</a></h2><div><div class="table-scroll"><table><thead><tr><th>構成</th><th>入力や表示の調整役</th><th>よくある名前</th></tr></thead><tbody><tr><td>MVC</td><td>Controller が入力を受け、Model を操作し View へ渡す</td><td>OrderController / Order / OrderView</td></tr><tr><td>MVP</td><td>Presenter が View の契約を通じて表示を調整する</td><td>OrderPresenter / IOrderView</td></tr><tr><td>MVVM</td><td>ViewModel が表示状態・操作を公開し、View がバインドする</td><td>OrderViewModel / OrderView</td></tr></tbody></table></div><p>MVC は Web フレームワークとデスクトップ UI で流れが異なることがあります。上の表は役割を理解するための概略です。採用するフレームワークの責務分担も合わせて確認します。Model は DB のテーブルだけを意味しません。</p></div><h2 id="mvvm-の-model-と-viewmodel" tabindex="-1">MVVM の Model と ViewModel <a class="header-anchor" href="#mvvm-の-model-と-viewmodel" aria-label="Permalink to &quot;MVVM の Model と ViewModel&quot;">​</a></h2><div><p><code>Order</code> は業務上の注文、<code>OrderViewModel</code> は画面に必要な選択中の注文・読込中フラグ・エラーメッセージを持つ、と分けられます。ViewModel から UI コントロールを直接操作すると、表示技術へ結び付きやすくなります。</p><p>C# の XAML 系 UI では <code>INotifyPropertyChanged</code> や <code>ICommand</code> がよく現れます。<code>ObservableObject</code> や <code>RelayCommand</code> はライブラリで提供される典型名で、C# 言語の予約語ではありません。</p></div><h2 id="言語と設計方式は一対一ではない" tabindex="-1">言語と設計方式は一対一ではない <a class="header-anchor" href="#言語と設計方式は一対一ではない" aria-label="Permalink to &quot;言語と設計方式は一対一ではない&quot;">​</a></h2><div><p>MVVM は C# 専用ではなく、C++ の UI フレームワークでも似た分離を実現できます。一方、コンソールの小さな変換ツールに ViewModel を導入しても、表示状態がほとんどなければ恩恵は限定的です。UI の規模と、バインディングなどフレームワークの仕組みに合わせます。</p></div><h2 id="controller-を薄く保つ理由" tabindex="-1">Controller を薄く保つ理由 <a class="header-anchor" href="#controller-を薄く保つ理由" aria-label="Permalink to &quot;Controller を薄く保つ理由&quot;">​</a></h2><div><p>Controller は入力を解釈し、ユースケースを呼び、結果を HTTP 応答などへ変換します。送料・割引・在庫の業務判断がすべて Controller に入ると、別の入口から再利用しづらくなります。一方、Application Service に全判断を移すだけでも巨大化は解決しません。ルールを適切なモデルへ寄せます。</p><aside class="article-note"><strong>よくある落とし穴</strong><p>ViewModel を API の DTO と共用すると、画面専用の状態が通信の契約へ漏れます。偶然同じ項目でも、変更理由が違うかを確認しましょう。</p></aside></div><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><p>画面を Web からデスクトップへ変える場合、残せる業務ロジックはどれですか？</p><h2 id="この章の参考資料" tabindex="-1">この章の参考資料 <a class="header-anchor" href="#この章の参考資料" aria-label="Permalink to &quot;この章の参考資料&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/windows/apps/develop/data-binding/data-binding-and-mvvm" target="_blank" rel="noreferrer">Data binding and MVVM</a> — Microsoft Learn。View・ViewModel・Model の分離と、データバインディング。</li><li><a href="https://learn.microsoft.com/dotnet/desktop/wpf/advanced/commanding-overview" target="_blank" rel="noreferrer">Commanding overview — WPF</a> — Microsoft Learn。操作の意味を入力装置から切り離すコマンド。</li><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/modern-web-apps-azure-architecture/common-web-application-architectures" target="_blank" rel="noreferrer">Common web application architectures</a> — Microsoft Learn。レイヤーと、Application Core へ向ける依存関係。</li></ul><p><a href="/study/design/naming.html">クラス名辞典</a> / <a href="/study/design/pattern-index.html">パターン一覧</a> / <a href="/study/design/notebook-references.html">手帖の参考資料</a></p>',17)])])}const V=t(d,[["render",i]]);export{p as __pageData,V as default};
